package com.mod.htgt6.minecraft1202.Module.Gameplay.Modern;
import cpw.mods.fml.common.eventhandler.*;import cpw.mods.fml.common.gameevent.TickEvent;import net.minecraftforge.event.world.WorldEvent;import net.minecraftforge.event.entity.player.*;import net.minecraftforge.event.entity.living.LivingAttackEvent;import net.minecraft.entity.player.*;import net.minecraft.entity.monster.EntityIronGolem;import net.minecraft.init.Items;import net.minecraft.item.*;import net.minecraft.world.World;
/** Server-side additions use Forge events rather than replacing legacy entity classes. */
public final class Parity115 implements cpw.mods.fml.common.IFuelHandler {
 @SubscribeEvent public void load(WorldEvent.Load e){for(String key:new String[]{"doInsomnia","drowningDamage","fallDamage","fireDamage"})if(!e.world.getGameRules().hasRule(key))e.world.getGameRules().addGameRule(key,"true");if(!e.world.getGameRules().hasRule("doImmediateRespawn"))e.world.getGameRules().addGameRule("doImmediateRespawn","false");}
 @SubscribeEvent public void damage(LivingAttackEvent e){if(e.entityLiving.worldObj.isRemote)return;String key=e.source==net.minecraft.util.DamageSource.drown?"drowningDamage":e.source==net.minecraft.util.DamageSource.fall?"fallDamage":e.source.isFireDamage()?"fireDamage":null;if(e.entityLiving instanceof EntityPlayer&&key!=null&&!e.entityLiving.worldObj.getGameRules().getGameRuleBooleanValue(key))e.setCanceled(true);}
 @SubscribeEvent(priority=EventPriority.LOWEST) public void repair(EntityInteractEvent e){if(e.isCanceled()||!(e.target instanceof EntityIronGolem))return;ItemStack held=e.entityPlayer.getHeldItem();EntityIronGolem golem=(EntityIronGolem)e.target;if(held==null||held.getItem()!=Items.iron_ingot||golem.getHealth()>=golem.getMaxHealth())return;e.setCanceled(true);if(golem.worldObj.isRemote)return;golem.heal(25);if(!e.entityPlayer.capabilities.isCreativeMode)--held.stackSize;golem.playSound("htgt6:entity.iron_golem.repair",1,1);}
 @SubscribeEvent public void respawn(TickEvent.PlayerTickEvent e){if(e.phase==TickEvent.Phase.END&&e.player instanceof EntityPlayerMP&&e.player.getHealth()<=0&&!e.player.worldObj.getWorldInfo().isHardcoreModeEnabled()&&e.player.worldObj.getGameRules().getGameRuleBooleanValue("doImmediateRespawn"))((EntityPlayerMP)e.player).playerNetServerHandler.processClientStatus(new net.minecraft.network.play.client.C16PacketClientStatus(net.minecraft.network.play.client.C16PacketClientStatus.EnumState.PERFORM_RESPAWN));}
 @SubscribeEvent(priority=EventPriority.LOWEST) public void bed(PlayerInteractEvent e){if(e.isCanceled()||e.action!=PlayerInteractEvent.Action.RIGHT_CLICK_BLOCK||e.world.isRemote||!e.world.isDaytime()||!e.world.provider.canRespawnHere())return;net.minecraft.block.Block b=e.world.getBlock(e.x,e.y,e.z);if(!b.isBed(e.world,e.x,e.y,e.z,e.entityPlayer))return;int x=e.x,z=e.z,meta=e.world.getBlockMetadata(x,e.y,z);if((meta&8)==0){int facing=meta&3;x+=net.minecraft.util.Direction.offsetX[facing];z+=net.minecraft.util.Direction.offsetZ[facing];}e.entityPlayer.setSpawnChunk(new net.minecraft.util.ChunkCoordinates(x,e.y,z),false);e.entityPlayer.addChatMessage(new net.minecraft.util.ChatComponentTranslation("block.minecraft.set_spawn"));}
 public int getBurnTime(ItemStack stack){Item item=stack.getItem();if(item instanceof net.minecraft.item.ItemBoat||item instanceof com.mod.htgt6.minecraft1202.Module.Items.Combat.ItemCombatBoat)return 1200;if(net.minecraft.block.Block.getBlockFromItem(item)==com.mod.htgt6.minecraft1202.Module.Registry.VillageAndPillage.VillagePillageContent.scaffolding)return 400;return 0;}
}
